ROOT=Path(__file__).parent
base='''[hidden]{display:none!important}*{box-sizing:border-box}html{scroll-padding-top:24px}body{margin:0;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.5}a{color:inherit;text-underline-offset:5px}button,input{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}h1,h2,h3,p,figure{margin:0}h1,h2{text-wrap:balance}img{display:block;width:100%}button,.button{display:inline-flex;justify-content:center;align-items:center;min-height:48px;padding:12px 22px;border:1px solid currentColor;text-decoration:none;font-weight:600}button:active,.button:active{opacity:.7}input{width:100%;min-height:48px;border:1px solid currentColor;border-radius:0;background:transparent;color:inherit;padding:12px}label{display:block;font-size:14px;font-weight:600}label input{margin-top:8px}form{display:grid;gap:20px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.14em;font-weight:600}.status{min-height:24px;font-size:14px}.skip{position:absolute;top:-100px;left:16px;padding:12px;background:white;color:black;z-index:100}.skip:focus{top:8px}.demo{font-size:12px}.wrap{max-width:1320px;margin:auto}.muted{opacity:.75}footer{font-size:13px}section{scroll-margin-top:24px}@media(max-width:700px){.fields{grid-template-columns:1fr}nav{gap:16px!important}button,.button{padding:12px 18px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}'''

def page(id,title,css,body,script=''):
    d=ROOT/id;d.mkdir(exist_ok=True)
    (d/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><style>{base}{css}</style></head><body><a class="skip" href="#main">Skip to content</a>{body}<script>{script}</script></body></html>',encoding='utf-8')

def form(id,button,status,date=False):
    return f'''<form data-testid="{id}"><div class="fields"><label>Your name <span aria-hidden="true">*</span><input required name="name" autocomplete="name"></label><label>Email address <span aria-hidden="true">*</span><input required type="email" name="email" autocomplete="email"></label></div>{'<label>Preferred date *<input type="date" name="date" required></label>' if date else ''}<div><button type="submit">{button} <span aria-hidden="true">&nbsp;↗</span></button></div><p class="status" role="status" data-testid="{status}"></p></form>'''

formjs="""document.querySelectorAll('form[data-testid]').forEach(f=>{if(f.dataset.testid==='catalogue-form'||f.dataset.testid==='batch-form')return;f.addEventListener('submit',e=>{e.preventDefault();let s=f.querySelector('[role=status]');s.textContent=f.dataset.testid==='appointment-form'?'Your appointment request has been recorded locally. This is a request only, not a booked appointment. No data has been sent.':'Thank you. Your request has been recorded in this local demonstration only. No data has been sent.';});});"""

