page('intervals','Intervals — Between the ordinary.', '''body{font-family:Helvetica,Arial,sans-serif;background:#111;color:#fff}header{padding:28px 48px;border-bottom:1px solid #444;display:flex;align-items:center;justify-content:space-between}.logo{font-size:32px;letter-spacing:-1.8px;text-decoration:none;font-weight:600}nav{display:flex;gap:36px;font-size:14px}nav a{text-decoration:none}.intro{padding:76px 48px 60px;display:grid;grid-template-columns:1.35fr 1fr;gap:64px;align-items:end}h1{font-size:clamp(56px,6.7vw,96px);line-height:.97;letter-spacing:-.065em;font-weight:400;max-width:760px}.intro .eyebrow{margin-bottom:32px;color:#bbb}.intro p{font-size:18px;line-height:1.6;max-width:460px}.intro .link{display:inline-block;margin-top:24px;font-size:14px}.works{padding:0 48px 80px;display:grid;grid-template-columns:1fr 1fr;gap:64px 40px}.image{height:480px;background:#080808;display:flex;justify-content:center;padding:24px}.image img{height:100%;width:100%;object-fit:contain;filter:grayscale(1)}figcaption{display:flex;gap:24px;padding-top:20px;font-size:14px;line-height:1.6}.worknum{font-size:12px;color:#aaa}figcaption strong{font-weight:500}figcaption small{display:block;color:#aaa;margin-top:8px;font-size:12px}.artists{border-top:1px solid #555;padding:64px 48px 80px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:48px}.artists h2,.enquiry h2{font-size:36px;font-weight:400;letter-spacing:-.04em}.artists h3{font-size:22px;font-weight:400;margin-bottom:16px}.artists p{font-size:16px;color:#ccc;max-width:380px}.enquiry{background:#eee;color:#111;padding:72px 48px;display:grid;grid-template-columns:1fr 1fr;gap:80px}.enquiry h2{font-size:48px;margin:16px 0}.enquiry p{max-width:380px}button{background:#111;color:#fff}footer{padding:28px 48px;display:flex;justify-content:space-between;color:#bbb}@media(max-width:700px){header{padding:20px}.logo{font-size:27px}nav{font-size:12px}nav a:last-child{display:none}.intro{padding:48px 20px 36px;grid-template-columns:1fr;gap:32px}.intro .eyebrow{margin-bottom:24px}h1{font-size:62px}.intro p{font-size:16px}.works{padding:0 20px 48px;grid-template-columns:1fr;gap:40px}.image{height:390px;padding:16px}.artists{padding:48px 20px;grid-template-columns:1fr;gap:32px}.enquiry{padding:48px 20px;grid-template-columns:1fr;gap:32px}.enquiry h2{font-size:38px}footer{padding:24px 20px;display:block}footer p+p{margin-top:8px}}''', f'''<header><a href="#main" class="logo">Intervals</a><nav aria-label="Main"><a href="#works">Selected works</a><a href="#artists">The artists</a><a href="#enquiry">Enquiries ↗</a></nav></header><main id="main"><section class="intro wrap"><div><div class="eyebrow">A conversation in photographs</div><h1>Between<br>the ordinary.</h1></div><div><p>A street before the city wakes. People held between departure and arrival. Light caught on the surface of water. Intervals brings photographs by Eugène Atget and Alfred Stieglitz into conversation.</p><a class="link" href="#works">Explore the selected works ↓</a></div></section><section class="works wrap" id="works" aria-label="Selected works">{gallery}</section><section class="artists wrap" id="artists"><h2>Two ways<br>of seeing.</h2><article><h3>Eugène Atget</h3><p>Atget photographed the streets, shopfronts and gardens of Paris. His attentive records turn everyday places into quietly compelling images.</p></article><article><h3>Alfred Stieglitz</h3><p>Photographer and advocate for photography as an art form, Stieglitz explored the life of the modern city through light, structure and the human figure.</p></article></section><section class="enquiry" id="enquiry"><div><div class="eyebrow">Continue the conversation</div><h2>Exhibition enquiries.</h2><p>Ask about the photographs and the ideas that bring them together.</p><p class="demo" style="margin-top:24px">Fictional client · Local demonstration.<br>This form does not send data.</p></div>{form('enquiry-form','Send an enquiry','form-status')}</section></main><footer><p>Intervals — Photography in conversation</p><p>Images: Cleveland Museum of Art · CC0</p></footer>''',formjs)

